    evt.SetFacetBit(58, FaceAttribute.Invisible, 1)
    evt.SetFacetBit(58, FaceAttribute.Untouchable, 1)
    evt.SetFacetBit(59, FaceAttribute.Invisible, 1)
    evt.SetFacetBit(59, FaceAttribute.Untouchable, 1)
    evt.SetFacetBit(108, FaceAttribute.Invisible, 1)
    evt.SetFacetBit(108, FaceAttribute.Untouchable, 1)
    evt.SetFacetBit(107, FaceAttribute.Invisible, 0)
    evt.SetFacetBit(107, FaceAttribute.Untouchable, 0)
end, nil)

-- evt:strongbox
RegisterEvent(27, "Chest", function()
    if not (not (IsQBitSet(QBit(113223)))) then
        XeenQuests.hook("q-d11.fort_search")
        return
    end
    evt.OpenChest(2)
    XeenQuests.hook("q-d11.fort_search")
end, "Chest")

-- evt:arrive
RegisterEvent(28, nil, function()
    if IsAtLeast(MapVar(6), 1) then
        return
    end
    SetValue(MapVar(6), 1)
    evt.SimpleMessage("Ogre Pass: a fort of the ogres on its knoll, timber and hides inside a log palisade, and another across the road joined to it under the pass. Kramer pays for burned forts; Graalg keeps what he takes in his own quarters in the east fort.")
end, nil)

